 /// 🌱️ Initializes only the fixed empty frontier without allocating or probing original input.
 pub fn new(expected:usize)->Self{Self{rows:ManuallyDrop::new(std::array::from_fn(|_|None)),levels:ManuallyDrop::new(std::array::from_fn(|_|None)),carry:ManuallyDrop::new(None),output:ManuallyDrop::new(None),page:ManuallyDrop::new(None),born:ManuallyDrop::new(None),retirement:Default::default(),counts:[0;LEVELS],expected,adopted:0,row_count:0,level:0,close_index:0,phase:Phase::Wait,finishing:false,closing:false}}
 /// 🚪️ Only the current original stream position may supply another owned row header.
