 pub fn begin_close_demand(&self)->RetirementDemand{if self.closing{Default::default()}else{RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()}}}
 pub fn begin_close_work_demand(&self)->u64{u64::from(!self.closing)}
