 pub fn close_original_into<'r>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||self.retirement.is_empty(){return Err(refusal("persistent builder original close has no selected child"))}self.retirement.step_original_into(original,body,effect,reply)}
 pub fn recover_close_original_into<'r>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'r,RetainedCloneStep,crate::OriginalRetirementFailure>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'r,RetainedCloneStep,crate::OriginalRetirementFailure>,ValueError>{if !self.closing||self.retirement.is_empty(){return Err(refusal("persistent builder original recovery has no selected child"))}self.retirement.recover_step_original_into(original,body,effect,reply)}
 /// 🧹️ Terminal owned custody is determined from real slots and the actual native cleanup frontier.
 pub fn terminal_is_empty(&self)->bool{self.page.is_none()&&self.born.is_none()&&self.rows.iter().all(Option::is_none)&&self.levels.iter().all(Option::is_none)&&self.carry.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
